-- AI Product Search & Intelligence Engine
-- Run this file in your MySQL server to create the DB, table, and seed data.
-- Example: mysql -u root -p < schema.sql

CREATE DATABASE IF NOT EXISTS product_search_db;
USE product_search_db;

CREATE TABLE IF NOT EXISTS products (
    id           INT AUTO_INCREMENT PRIMARY KEY,
    product_id   VARCHAR(20)     NOT NULL UNIQUE,
    name         VARCHAR(255)    NOT NULL,
    description  TEXT            NOT NULL,
    price        DECIMAL(10, 2)  NOT NULL,
    category     VARCHAR(100),
    brand        VARCHAR(100),
    color        VARCHAR(50)
);

-- IGNORE makes this seed script safe to run again without duplicating products.
